// Helper to get a component by id and create instance
const inst = (id, x, y, w, h) => {
  const node = figma.getNodeById(id);
  if (!node || node.type !== "COMPONENT") { return null; }
  const c = node.createInstance();
  c.x = x; c.y = y;
  if (w) c.resize(w, h); else if (node.width) c.resize(node.width, node.height);
  return c;
};

// Helper create frame
const frame = (name, x, y, w, h, fill) => {
  const f = figma.createFrame();
  f.name = name; f.x = x; f.y = y;
  f.resize(w, h);
  f.fills = fill ? [{type:"SOLID", color: fill}] : [];
  f.fills = fill ? [{type:"SOLID", color: fill}] : [{type:"SOLID", color:{r:1,g:1,b:1}}];
  f.clipsContent = true;
  return f;
};

// Helper text
const txt = (parent, content, x, y, size, weight, color, width) => {
  const t = figma.createText();
  t.fontName = {family: fam, style: weight};
  t.fontSize = size;
  t.fills = [{type:"SOLID", color: color}];
  t.characters = content;
  t.x = x; t.y = y;
  if (width) { t.resize(width, t.height); }
  if (parent) parent.appendChild(t);
  return t;
};

// rect helper
const rect = (parent, x, y, w, h, fill, radius) => {
  const r = figma.createRectangle();
  r.x = x; r.y = y; r.resize(w, h);
  r.fills = [{type:"SOLID", color: fill}];
  if (radius) r.cornerRadius = radius;
  if (parent) parent.appendChild(r);
  return r;
};

